import{_ as a,o,c as t,a2 as s}from"./chunks/framework.DCVnL8g5.js";const p=JSON.parse('{"title":"Introducción y casos de uso","description":"","frontmatter":{},"headers":[],"relativePath":"full-stack/frontend/redux/01-introduccion-y-casos-de-uso.md","filePath":"full-stack/frontend/redux/01-introduccion-y-casos-de-uso.md","lastUpdated":1789040978000,"isDraft":false}'),r={name:"full-stack/frontend/redux/01-introduccion-y-casos-de-uso.md"};function n(i,e,l,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="introduccion-y-casos-de-uso" tabindex="-1">Introducción y casos de uso <a class="header-anchor" href="#introduccion-y-casos-de-uso" aria-label="Permalink to &quot;Introducción y casos de uso&quot;">​</a></h1><p>Redux guarda <strong>estado global</strong> en un único store y lo cambia solo con <strong>acciones</strong>. La UI no muta el estado a escondidas: despacha, el reducer calcula el siguiente valor, la UI se vuelve a pintar.</p><p>Tres piezas que no son lo mismo:</p><table tabindex="0"><thead><tr><th>Qué</th><th>Paquete / idea</th><th>Para qué</th></tr></thead><tbody><tr><td><strong>Redux</strong></td><td>El modelo: store, <code>dispatch</code>, reducer, estado.</td><td>Coordinar estado compartido.</td></tr><tr><td><strong>Redux Toolkit (RTK)</strong></td><td><code>@reduxjs/toolkit</code></td><td>Forma <strong>oficial y recomendada</strong> de escribir Redux hoy.</td></tr><tr><td><strong>React-Redux</strong></td><td><code>react-redux</code></td><td>Conectar ese store a componentes React (<code>Provider</code>, <code>useSelector</code>, <code>useDispatch</code>).</td></tr></tbody></table><p>Redux no exige React. Este manual vive en frontend y los ejemplos usan React porque es el caso habitual. Documentación: <a href="https://redux.js.org/introduction/why-rtk-is-redux-today" target="_blank" rel="noreferrer">Why RTK is how to use Redux today</a>, <a href="https://redux.js.org/tutorials/essentials/part-1-overview-concepts" target="_blank" rel="noreferrer">Redux Essentials</a>, <a href="https://redux-toolkit.js.org/introduction/getting-started" target="_blank" rel="noreferrer">Getting Started (RTK)</a>, <a href="https://react-redux.js.org/" target="_blank" rel="noreferrer">React-Redux</a>.</p><h2 id="el-flujo" tabindex="-1">El flujo <a class="header-anchor" href="#el-flujo" aria-label="Permalink to &quot;El flujo&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UI  →  dispatch(action)  →  store / reducer  →  nuevo estado  →  UI</span></span></code></pre></div><p>Unidireccional: no hay “el componente escribió en el store”. La extensión <strong>Redux DevTools</strong> enseña cada acción y el estado resultante; instálala en el navegador y RTK la conecta por defecto.</p><h2 id="estado-local-global-servidor" tabindex="-1">Estado local, global, servidor <a class="header-anchor" href="#estado-local-global-servidor" aria-label="Permalink to &quot;Estado local, global, servidor&quot;">​</a></h2><ul><li><strong>Local:</strong> un input, un modal, un acordeón. <code>useState</code> o estado del propio componente.</li><li><strong>Cliente global:</strong> lo que varias zonas deben ver igual <em>ahora</em>: sesión/auth metadata, carrito con reglas, filtros de un tablero, un wizard de varios pasos, preferencias de UI.</li><li><strong>Servidor:</strong> el origen de verdad está en la API (lista de tareas, perfil). Eso es <strong>caché</strong>, no “el store como base de datos”. En Redux moderno va a <strong>RTK Query</strong> (capítulo 6), no a un <code>fetch</code> + flags a mano.</li></ul><h2 id="cuando-tiene-sentido" tabindex="-1">Cuándo tiene sentido <a class="header-anchor" href="#cuando-tiene-sentido" aria-label="Permalink to &quot;Cuándo tiene sentido&quot;">​</a></h2><ul><li>Auth/sesión que leen header, rutas y varios paneles.</li><li>Carrito o tablero con reglas (cantidades, estados, undo).</li><li>Preferencias o flags que atraviesan layouts.</li><li>Workflows compartidos (selección + panel de detalle + atajos).</li></ul><h2 id="cuando-no-lo-necesitas" tabindex="-1">Cuándo no lo necesitas <a class="header-anchor" href="#cuando-no-lo-necesitas" aria-label="Permalink to &quot;Cuándo no lo necesitas&quot;">​</a></h2><p>Una ficha con tres <code>useState</code>, un formulario aislado, o datos que solo vive un hook de React Query / el propio framework. Context basta para un tema o un usuario ya resuelto. <strong>Redux no es obligatorio</strong> en un proyecto React.</p><p>El dominio del manual: un <strong>tablero de tareas</strong> (título, hecha, autor). Los capítulos 2–3 montan el store; 4 y 6 se reparten async (thunk vs Query); 5 normaliza; 7–9 cierran efectos, tests y criterios.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Meter <em>todo</em> el árbol de React en Redux “por si acaso”.</li><li>Tratar el store como caché HTTP sin RTK Query (duplicas loading, refetch y consistencia).</li><li>Empezar una app nueva con <code>createStore</code> + <code>switch</code> + constantes: es el núcleo, no el camino actual.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Empieza con RTK (<code>configureStore</code>, <code>createSlice</code>). El core clásico sirve para <em>entender</em>, no para el esqueleto del repo.</li><li>Pregunta: ¿quién más necesita este dato? Si la respuesta es “este componente”, no es Redux.</li><li>Abre DevTools el primer día: ver acciones es más barato que adivinar.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Lista tres estados de una app que uses y clasifícalos: local / cliente global / servidor.</li><li>Instala Redux DevTools y reconoce la lista de acciones (aunque aún vacía).</li><li>Lee <em>Why RTK is how to use Redux today</em> y anota qué APIs sustituyen al boilerplate clásico.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-store-actions-reducers-y-dispatch">Store, actions, reducers y dispatch</a>.</p>',23)])])}const g=a(r,[["render",n]]);export{p as __pageData,g as default};
